Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -105,4 +105,30 @@
  // nape weak point marker
  ctx.fillStyle='rgba(214,92,66,.85)';ctx.beginPath();ctx.ellipse(-7,-110,5,8,-.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f0cf88';ctx.beginPath();ctx.arc(-7,-110,2,0,Math.PI*2);ctx.fill();
  if(t.hitFlash>0){ctx.strokeStyle='rgba(255,235,199,.8)';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-88,36,0,Math.PI*2);ctx.stroke();}
  ctx.restore();}
+function drawPlayer(){const p=game.player;if(!p)return;const x=worldX(p.x),y=p.y;ctx.save();ctx.translate(x,y);ctx.rotate(p.angle*.35);
+ // cloak trailing in motion
+ ctx.fillStyle='#74846f';ctx.beginPath();ctx.moveTo(-2,-30);ctx.quadraticCurveTo(-17,-18,-21,-1);ctx.lineTo(-2,-7);ctx.lineTo(7,-24);ctx.fill();
+ // legs, harness body
+ ctx.strokeStyle='#c9c0a9';ctx.lineWidth=6;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-4,-13);ctx.lineTo(-7,0);ctx.moveTo(4,-13);ctx.lineTo(8,0);ctx.stroke();
+ ctx.fillStyle='#d5c9ad';ctx.fillRect(-6,-29,12,17);ctx.fillStyle='#5e716b';ctx.fillRect(-5,-28,10,9);ctx.fillStyle='#a6865c';ctx.fillRect(-9,-17,18,4);
+ // harness lines
+ ctx.strokeStyle='#b9aa89';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(-5,-27);ctx.lineTo(0,-14);ctx.lineTo(6,-27);ctx.stroke();
+ // head and scarf
+ ctx.fillStyle='#c49c7a';ctx.beginPath();ctx.arc(0,-36,6.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#52473b';ctx.beginPath();ctx.arc(0,-38,6,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#a44f3c';ctx.fillRect(-5,-31,10,3);
+ // blades
+ ctx.strokeStyle='#d8d6c9';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,-18);ctx.lineTo(-16,-32);ctx.moveTo(8,-18);ctx.lineTo(16,-32);ctx.stroke();
+ if(p.rope){const a=p.rope;ctx.setTransform(DPR,0,0,DPR,0,0);ctx.strokeStyle='rgba(225,219,196,.8)';ctx.lineWidth=1.3;ctx.beginPath();ctx.moveTo(worldX(p.x),p.y-25);ctx.lineTo(worldX(a.x),a.y);ctx.stroke();ctx.fillStyle='#e2c481';ctx.beginPath();ctx.arc(worldX(a.x),a.y,3,0,Math.PI*2);ctx.fill();}
+ ctx.restore();
+ // speed streaks
+ if(keys.boost&&game.fuel>0){for(let i=0;i<3;i++){ctx.strokeStyle=`rgba(231,214,177,${.35-i*.08})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x-rand(20,65),y-rand(-4,15));ctx.lineTo(x-rand(10,30),y-rand(-4,15));ctx.stroke();}}
+}
+function drawParticles(dt){for(let i=game.particles.length-1;i>=0;i--){const p=game.particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.gravity*dt;p.life-=dt;if(p.life<=0){game.particles.splice(i,1);continue;}ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(worldX(p.x),p.y,p.size,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}
+function addBurst(x,y,color,n=18){for(let i=0;i<n;i++){const a=rand(0,Math.PI*2),speed=rand(35,210);game.particles.push({x,y,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed-35,gravity:150,life:rand(.35,.8),max:.8,size:rand(1,4),color});}}
+function render(dt){
+ ctx.save();if(game.shake>0){ctx.translate(rand(-game.shake,game.shake),rand(-game.shake*.5,game.shake*.5));game.shake=Math.max(0,game.shake-dt*20);}drawSky();drawBuildings();drawAnchors();
+ // titans sorted by world location for depth
+ game.titans.slice().sort((a,b)=>a.y-b.y).forEach(drawTitan);drawPlayer();drawParticles(dt);
+ if(game.player&&game.player.rope){const p=game.player,a=p.rope;const dx=worldX(a.x)-worldX(p.x),dy=a.y-(p.y-25),ang=Math.atan2(dy,dx);ctx.strokeStyle='rgba(224,195,129,.45)';ctx.lineWidth=1;ctx.beginPath();ctx.arc(worldX(a.x),a.y,16,ang-.22,ang+.22);ctx.stroke();}
+ ctx.restore();
+}

input.newString:
 ctx.restore();
}
function nearestAnchor(){const p=game.player;let best=null,dist=Infinity;for(const a of game.anchors){const d=Math.hypot(a.x-p.x,a.y-(p.y-25));if(d<dist&&d<430){best=a;dist=d;}}return best;}
function attachGrapple(){const p=game.player;if(!p||game.grappleCD>0)return;if(p.rope){p.rope=null;return;}const a=nearestAnchor();if(a){p.rope=a;game.grappleCD=.24;game.fuel=Math.max(0,game.fuel-1);toast('ANCHOR LOCKED');}}
function attack(){const p=game.player;if(!p||game.slashCD>0)return;game.slashCD=.42;let target=null,best=Infinity;
 for(const t of game.titans){if(!t.alive)continue;const dx=t.x-p.x,dy=(t.y-110*t.scale)-p.y,d=Math.hypot(dx,dy);if(Math.abs(dx)<92*t.scale&&Math.abs(dy)<92*t.scale&&d<best){best=d;target=t;}}
 if(target){target.hp-=1;target.hitFlash=.22;game.shake=5;game.score+=100+game.combo*25;game.combo++;game.comboTimer=2.2;addBurst(target.x-7,target.y-110*target.scale,'#e99c70',23);addBurst(target.x,target.y-95*target.scale,'#efe0b9',12);toast(game.combo>1?`CLEAN CUT  ×${game.combo}`:'PERFECT STRIKE');if(target.hp<=0){target.alive=false;game.kills++;game.score+=350;game.fuel=Math.min(100,game.fuel+13);addBurst(target.x,target.y-75*target.scale,'#d7c497',34);if(game.kills>=8){finish(true);}else{game.spawnTimer=1.1;}}}
 else {p.vx+=p.vx>=0?100:-100;}
}
function update(dt){sceneT+=dt;if(mode!=='playing')return;game.time+=dt;game.slashCD=Math.max(0,game.slashCD-dt);game.grappleCD=Math.max(0,game.grappleCD-dt);game.comboTimer-=dt;if(game.comboTimer<=0)game.combo=0;
 const p=game.player,ground=game.ground-18;let accel=keys.boost?670:370;
 if(keys.left)p.vx-=accel*dt;if(keys.right)p.vx+=accel*dt;
 if(keys.boost&&game.fuel>0){game.fuel=Math.max(0,game.fuel-21*dt);p.vx*=1+dt*1.35;p.vy-=70*dt;}else game.fuel=Math.min(100,game.fuel+5.5*dt);
 if(p.rope){const a=p.rope,dx=a.x-p.x,dy=a.y-(p.y-20),dist=Math.hypot(dx,dy)||1;const tension=(dist-135);p.vx+=(dx/dist)*tension*1.25*dt;p.vy+=(dy/dist)*tension*1.25*dt;p.vy+=235*dt;if(!keys.grapple&&dist<115){p.rope=null;}if(dist>510){p.rope=null;}}
 else {p.vy+=620*dt;}
 p.vx*=Math.pow(.984,dt*60);p.vy*=Math.pow(.992,dt*60);p.x+=p.vx*dt;p.y+=p.vy*dt;
 if(p.y>ground){p.y=ground;p.vy=Math.min(0,p.vy);p.rope=null;}
 if(p.y<H*.12){p.y=H*.12;p.vy=Math.max(0,p.vy);}
 p.x=Math.max(20,p.x);p.angle=clamp(p.vx/550,-1,1);
 if(keys.grapple&&!p.rope&&game.grappleCD<=0)attachGrapple();
 game.camera=Math.max(0,p.x-W*.36);
 // advance scenery and target wave
 for(const t of game.titans){if(!t.alive)continue;t.walk+=dt*2.7;t.x-=t.speed*dt;t.hitFlash=Math.max(0,t.hitFlash-dt);
  if(Math.abs(t.x-p.x)<58&&Math.abs(t.y-p.y)<120){p.vx+=(p.x<t.x?-1:1)*140*dt;game.fuel=Math.max(0,game.fuel-9*dt);}
  if(t.x<game.camera-90){t.alive=false;game.spawnTimer=Math.min(game.spawnTimer,.2);game.score=Math.max(0,game.score-100);toast('TITAN BREACHED THE LINE');}
 }
 game.titans=game.titans.filter(t=>t.alive||t.x>game.camera-200);
 game.spawnTimer-=dt;if(game.spawnTimer<=0&&game.kills<8){const last=Math.max(game.camera+W*.9,...game.titans.map(t=>t.x));spawnTitan(last+rand(W*.45,W*.75),rand(.8,1.3));game.spawnTimer=rand(2,3.8);}
 if(game.fuel<=0&&p.y>ground-10)p.vx*=.99;
 if(game.time>100){finish(false,'The district has fallen.');}
 updateHud();
}
function updateHud(){ $('kills').textContent=String(game.kills).padStart(2,'0');$('scoreVal').textContent=String(game.score).padStart(5,'0');const sec=Math.floor(game.time);$('timeVal').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;$('fuelText').textContent=`${Math.round(game.fuel)}%`;$('fuelBar').style.width=`${game.fuel}%`;
 const target=game.titans.find(t=>t.alive&&Math.abs(t.x-game.player.x)<340);$('titanHealth').classList.toggle('show',!!target);if(target){$('titanHpBar').style.width=`${target.hp*100}%`;$('titanHpText').textContent=target.hp?'100%':'0%';}}
function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1050);}
