function finish(won,msg=''){mode='over';$('pauseHint').classList.remove('show');showPanel(won?'win':'lose',msg);}
function pause(){if(mode==='playing'){mode='pause';showPanel('pause');}}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowleft','arrowright','arrowup','arrowdown'].includes(k))e.preventDefault();if(k==='escape'||k==='p'){if(mode==='playing')pause();else if(mode==='pause'){mode='playing';overlay.classList.add('hidden');}return;}if(mode!=='playing')return;
 if(k==='a'||k==='arrowleft')keys.left=true;if(k==='d'||k==='arrowright')keys.right=true;if(k==='shift'||k==='w'||k==='arrowup')keys.boost=true;if(k===' '){keys.grapple=true;}if(k==='j'||k==='enter')attack();});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();if(k==='a'||k==='arrowleft')keys.left=false;if(k==='d'||k==='arrowright')keys.right=false;if(k==='shift'||k==='w'||k==='arrowup')keys.boost=false;if(k===' ')keys.grapple=false;});
$('touchUi').querySelectorAll('[data-act]').forEach(btn=>{const action=btn.dataset.act;const down=e=>{e.preventDefault();btn.classList.add('down');if(action==='pause'){pause();return;}if(action==='slash'){attack();return;}keys[action]=true;};const up=e=>{e.preventDefault();btn.classList.remove('down');if(action!=='pause'&&action!=='slash')keys[action]=false;};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up);});
function frame(now){const dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render(dt);requestAnimationFrame(frame);}
resize();showPanel('menu');requestAnimationFrame(frame);
})();
</script>
</body>
</html>

